  ["362d3a10495f9fac"] = { "Non lo ammetto alla leggera, ma alla forgia sei molto più abile di me. Se vuoi imparare più dei miei modesti insegnamenti, ti suggerisco di cercare un nano di nome Therum Deepforge a ⟦Stormwind=Roccavento⟧. Lo troverai nel Dwarven District.", "." },
  ["363d54232fa4daf7"] = { "Il diario di Jandice Barov è pieno di farneticazioni e deliri sui non morti. Verso la fine del libro c'è quello che sembra uno schema di sartoria per creare una specie di borsa. Le tue conoscenze di sartoria non bastano per decifrare lo schema.", "." },
  ["363d6fbae389fd86"] = { "Birra a buon mercato! Prendete qui la vostra birra a buon mercato!", "." },
  ["36462069c74e9166"] = { "Trogg?! I trogg di cui parli sono gli stessi che ci sono oggi nel mondo?", "." },
  ["364778ea4e65ca8c"] = { "Scommetto che Josetta sarebbe più che felice di insegnarti qualche nuovo incantesimo. Probabilmente è su nella sua stanza al Lion's Pride Inn.", "." },
  ["3647febb2ac4123a"] = { "Ahhh... mio padre diceva sempre che non avrei mai combinato granché, e ora, steso sotto un albero mentre la vita mi abbandona, temo proprio che avesse ragione.\n\nAlmeno vorrei morire sapendo che il mio ultimo nemico giace morto.", "." },
  ["36488dc4ef214598"] = { "Ehi Pratt, puoi insegnarmi di nuovo a fare una ⟦Wild Leather Vest=Veste di Cuoio Selvatico⟧?", "." },
  ["365810df5b683e41"] = { "Quali merci ho il diritto di acquistare dai Profanatori?", "." },
  ["366207c702ac32ad"] = { "Tutta la potenza della natura è a mia disposizione, miseri mortali. Vediamo quale delle mie molte forme porrà fine alla vostra sofferenza!", "." },
  ["366450201d61ff57"] = { "%s indica con noncuranza il bersaglio orco...", "." },
  ["3669e1c1034ff12e"] = { "Unitevi a noi, o cadete per sempre!", "." },
  ["36746a27e59f0a48"] = { "Nessun fossile misterioso qui... Ah, ma la mia copia di ⟦Green Hills of Stranglethorn=Verdi Colline di Rovotorto⟧. Che bel libro!", "." },
  ["367b8d06f63ea774"] = { "Ma cosa... nessuno purifica un mezzorso nel MIO accampamento! Affronta l'ira di Xabraxxis!", "." },
  ["368a6e3fa4d5ac5a"] = { "Forse ce l'hai, forse no. Credo di avere un modo per scoprirlo...", "." },
  ["36a0217a632df83d"] = { "Tomas non sarà il miglior cuoco in circolazione, ma ha qualche piatto che fa proprio al caso tuo. Al momento lavora alla Lion's Pride Inn, se vuoi imparare la professione.", "." },
  ["36b5cbd557858ad8"] = { "Grazie per aver liberato me, mia sorella e tutti voi! Finalmente possiamo riposare in pace.", "." },
  ["36bed95a710c5740"] = { "Pace e pazienza siano con te, {name}. Resta sempre forte.", "." },
  ["36c5bdc348d1ae33"] = { "Miranda, puoi dirmi quanto costano in insegne gli oggetti che offri agli avventurieri con reputazione Reverito?", "." },
  ["36cbad5eb4364863"] = { "%s comincia ad armeggiare con gli occhiali davanti alla pietra.", "." },
  ["36d8875b35381c87"] = { "D'accordo, d'accordo! Credo di riuscire a capire come far funzionare questo coso...", "." },
  ["36dcbc2fd140552b"] = { "Kel'Thuzad dire di dirti... MUORI!", "." },
  ["36dcbf965b885c07"] = { "Le caverne sotto di noi sono una fonte di pelli strane e meravigliose, ma devi fare attenzione se ti avventuri nelle loro profondità, {name}. Ricorda che la tua pelle vale molto di più.", "." },
  ["36de48cbc9f53e97"] = { "Hai sentito la buona novella su Al'Akir, il Signore del Vento?", "." },
  ["36dfb7808ee38f0b"] = { "La Stormwind Counting House si trova vicino ai cancelli d'ingresso, nel Quartiere del Commercio di ⟦Stormwind=Roccavento⟧. E quando ti stanchi di contare i tuoi soldi, fai un salto alla Gilded Rose per bere qualcosa.", "." },
  ["36e385aaa6e5d7a7"] = { "%s si inchina profondamente davanti a te.", "." },
  ["36f72a0bc1640799"] = { "Osi sfidare il compito affidato allo Stormo dei Draghi Blu? MUORI, verme.", "." },
  ["36f8f4a2c3d11b3c"] = { "Non ti deluderà, <viaggiatore/viaggiatrice>. La sartoria è un'attività piena di gioia.", "." },
